import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"서울과 지하철 레이어","description":"","frontmatter":{},"headers":[],"relativePath":"world/World-and-Subway-Layers.md","filePath":"world/World-and-Subway-Layers.md"}'),o={name:"world/World-and-Subway-Layers.md"};function i(l,t,s,c,n,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="서울과-지하철-레이어" tabindex="-1">서울과 지하철 레이어 <a class="header-anchor" href="#서울과-지하철-레이어" aria-label="Permalink to &quot;서울과 지하철 레이어&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-subway-layers.svg?raw=true" alt="지하철 다층 공간의 인물 방향 시야 연결"></p><p>지하철 다층 구조에서 인물의 방향과 시야가 층간 이동 경로와 연결되는 방식을 파악합니다.</p><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/subway-layers.svg?raw=true" alt="지하철 중심 다층 도시"></p><h2 id="세계의-수직-구조" tabindex="-1">세계의 수직 구조 <a class="header-anchor" href="#세계의-수직-구조" aria-label="Permalink to &quot;세계의 수직 구조&quot;">​</a></h2><p>서울은 평면 행정구역 지도가 아니라 서로 다른 위험과 기능을 가진 층의 그래프입니다.</p><table tabindex="0"><thead><tr><th>층</th><th>주요 기능</th><th>대표 위험</th></tr></thead><tbody><tr><td>지상 폐허</td><td>자원 수집, 태양광, 장거리 관측</td><td>기후, 붕괴, 노출, 세력 충돌</td></tr><tr><td>역사 대합실</td><td>시장, 주거, 행정, 정보</td><td>과밀, 화재, 권력 분쟁</td></tr><tr><td>승강장·선로</td><td>이동, 방어선, 화물 운송</td><td>병목, 매복, 전력 차단</td></tr><tr><td>환승 통로</td><td>노선 간 정치·물류 연결</td><td>봉쇄, 통행세, 혼잡</td></tr><tr><td>심층 터널</td><td>은밀 이동, 정비 시설</td><td>침수, 어둠, 통신 단절</td></tr><tr><td>차량기지 인접 거점</td><td>수리, 부품, 대규모 저장</td><td>전략적 공성, 화재</td></tr></tbody></table><h2 id="그래프-구성" tabindex="-1">그래프 구성 <a class="header-anchor" href="#그래프-구성" aria-label="Permalink to &quot;그래프 구성&quot;">​</a></h2><p>세계 진실 그래프는 역, 구역과 연결을 모두 저장합니다. 화면은 그중 현재 필요한 노선과 선택한 역의 상세만 보여 줍니다.</p><ul><li><code>Station</code>: 역 사회와 전략 거점</li><li><code>StationLayer</code>: 대합실, 승강장, 심층 구역</li><li><code>SurfaceDistrict</code>: 역과 연결된 지상 권역</li><li><code>TunnelSegment</code>: 역 사이의 이동 구간</li><li><code>VerticalConnector</code>: 계단, 승강기, 환기구</li><li><code>Interchange</code>: 노선 사이의 환승 연결</li><li><code>StrategicSite</code>: 병원, 시장, 발전, 급수, 정비 거점</li></ul><h2 id="데이터-출처-구분" tabindex="-1">데이터 출처 구분 <a class="header-anchor" href="#데이터-출처-구분" aria-label="Permalink to &quot;데이터 출처 구분&quot;">​</a></h2><p>모든 노드와 연결에는 다음 출처 상태가 붙습니다.</p><ul><li><code>measured</code>: 공식 자료에서 직접 확인한 값</li><li><code>derived</code>: 확인된 자료에서 계산한 값</li><li><code>fictional</code>: 게임을 위해 창작한 값</li></ul><p>현재 검증된 승하차 자료는 역의 활동 가중치를 만드는 참고 자료로만 사용합니다. 실제 역 내부 구조, 붕괴 상태, 세력 배치와 전술 전장은 창작 원형입니다.</p><h2 id="동적-연결" tabindex="-1">동적 연결 <a class="header-anchor" href="#동적-연결" aria-label="Permalink to &quot;동적 연결&quot;">​</a></h2><p>연결은 삭제되지 않고 상태가 바뀝니다. 정상, 위험, 통제, 봉쇄, 침수, 붕괴, 임시 복구 상태와 원인을 기록합니다. 그래서 플레이어는 “왜 길이 끊겼는지”와 “무엇을 해결하면 다시 열리는지”를 확인할 수 있습니다.</p><p>이 연결이 실제 보급 처리량, 고립과 복구에 미치는 영향은 <a href="/world/Logistics-and-Infrastructure.html">물류와 기반 시설</a>, 연결된 역의 통제와 서비스는 <a href="/world/Strongholds-and-Territory.html">거점과 영토</a>에서 계산합니다.</p>',17)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
